  endpoint = '/api/automation/v1/categories/conversations/reply';
  body = { phone, source, reply: { raw_text: source.raw_text } };
} else if (parsed.intent === 'show_uncategorized_purchases') {
  endpoint = '/api/automation/v1/categories/uncategorized';
  body = { phone, source, month: parsed.month, year: parsed.year, period: parsed.period, limit: 12 };
} else if (parsed.intent === 'set_purchase_category') {
  endpoint = '/api/automation/v1/categories/apply-to-purchase';
  body = { phone, source, purchase_id: parsed.purchase_id, purchase_hint: parsed.purchase_hint, category_id: parsed.category_id, category_hint: parsed.category_hint, create_category: parsed.create_category === true };
} else if (parsed.intent === 'set_merchant_category_rule') {
