} else if (parsed.intent === 'help') {
  return [{ json: { send_direct: true, reply_text: parsed.reply_text || '🏷️ Posso te ajudar com categorias. Exemplos:\n• *compras sem categoria*\n• *compra #123 é Alimentação*\n• *sempre classifique iFood como Alimentação*' } }];
}
return [{ json: { endpoint, body, idempotency_key: `whatsapp-category:${source.instance}:${source.message_id}` } }];

